'use strict';
const MODE = location.protocol === 'file:' ? 'preview' : 'service';
const MODEL_NAMES = {'ec2':'EC2 / Auto Scaling','eks-ec2':'EKS on EC2','eks-fargate':'EKS on Fargate','ecs-ec2':'ECS on EC2','ecs-fargate':'ECS on Fargate','lambda':'Lambda','docker':'Docker','podman':'Podman','kubernetes':'Kubernetes','shared':'Shared / unclassified'};
const ROUTES = [
 ['overview','Overview','⊞','Workspace'],['connections','Connections','⌁','Workspace'],['inventory','Inventory','▤','Workspace'],
 ['scenarios','Scenarios','◇','Validation'],['runs','Execution records','▷','Validation'],['validations','Validation runs','✓','Validation'],['reports','Reports','▧','Validation'],
 ['roadmap','Goal & roadmap','↗','System'],['data','Data & security','▣','System']
];
const state = {mode:MODE,token:'',unlocked:false,entries:[],audit:[],connections:[],route:'overview',filters:{},inventoryRef:'latest',inventoryLimit:200,busy:false,importRaw:'',importReviewed:false};
const $ = (s,root=document)=>root.querySelector(s);
const $$ = (s,root=document)=>Array.from(root.querySelectorAll(s));
const esc = value=>String(value ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const rid = r=>`${r.kind}:${r.id}@${r.revision}`;
const records = kind=>state.entries.filter(e=>e.record.kind===kind);
const get = reference=>state.entries.find(e=>e.meta.ref===reference);
const clone = value=>JSON.parse(JSON.stringify(value));
const now = ()=>new Date().toISOString();
const shortDate = value=>{if(!value)return 'Not recorded';const d=new Date(value);return Number.isNaN(d.getTime())?'Invalid timestamp':d.toLocaleString('en-GB',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit',timeZone:'UTC'})+' UTC';};
const badge = (value,label)=>`<span class="badge ${esc(String(value).toLowerCase().replace(/[^a-z_-]/g,''))}">${esc(label||String(value).replaceAll('_',' '))}</span>`;
const tags = models=>models.map(m=>`<span class="badge">${esc(MODEL_NAMES[m]||m)}</span>`).join(' ');
const button = (label,action,extra='',secondary=false)=>`<button class="button ${secondary?'secondary':''}" data-action="${action}" ${extra}>${label}</button>`;
function toast(message,error=false){const el=$('#toast');el.textContent=message;el.classList.toggle('error',error);el.hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>{el.hidden=true;},7000);}
function stable(value){if(Array.isArray(value))return '['+value.map(stable).join(',')+']';if(value&&typeof value==='object')return '{'+Object.keys(value).sort().map(k=>JSON.stringify(k)+':'+stable(value[k])).join(',')+'}';return JSON.stringify(value);}
async function hash(value){if(!crypto.subtle)return 'unavailable-in-this-browser';const b=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(stable(value)));return Array.from(new Uint8Array(b)).map(v=>v.toString(16).padStart(2,'0')).join('');}
function download(name,body,type='application/json'){const url=URL.createObjectURL(body instanceof Blob?body:new Blob([body],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function api(path,options={}){if(!state.token)throw new Error('Unlock the local service first.');const opts={method:options.method||'GET',headers:{'Authorization':'Bearer '+state.token},credentials:'omit'};if(options.body!==undefined){opts.headers['Content-Type']='application/json';opts.body=options.raw?options.body:JSON.stringify(options.body);}const response=await fetch('/api/'+path,opts);if(!response.ok){let message='Request failed ('+response.status+').';try{const error=await response.json();message=typeof error.detail==='string'?error.detail:JSON.stringify(error.detail,null,2);}catch(_){}throw new Error(message);}return options.blob?response.blob():response.json();}
async function refresh(){if(state.mode!=='service'||!state.unlocked)return;const [workspace,config]=await Promise.all([api('workspace'),api('config')]);state.entries=workspace.records;state.audit=workspace.audit;state.connections=config.connections;render();}
function latestSnapshots(){const latest=new Map();for(const e of records('snapshot')){const k=e.record.data.connection_id;const old=latest.get(k);if(!old||new Date(e.record.data.ended_at)>=new Date(old.record.data.ended_at))latest.set(k,e);}return Array.from(latest.values());}
function snapshotStatus(e){return e.record.data.coverage.some(c=>!['complete','not_requested'].includes(c.status))?'partial':'complete';}
function refButton(reference,label){return `<button class="text-link" data-action="detail" data-ref="${esc(reference)}">${esc(label||reference)}</button>`;}
function originBadge(e){return e.record.simulated?badge('simulated','Synthetic fixture'):badge(e.meta.origin,e.meta.origin==='evaluated'?'Computed here':e.meta.origin==='imported'?'Imported · unverified':e.meta.origin.replaceAll('-',' '));}
function pageHeading(eyebrow,title,description,actions=''){return `<div class="page-heading"><div><div class="eyebrow">${esc(eyebrow)}</div><h1>${esc(title)}</h1><p>${esc(description)}</p></div>${actions?`<div class="heading-actions">${actions}</div>`:''}</div>`;}
function panel(title,subtitle,body,action=''){return `<section class="panel"><div class="panel-header"><div><h2>${esc(title)}</h2>${subtitle?`<p>${esc(subtitle)}</p>`:''}</div>${action}</div>${body}</section>`;}
function empty(title,description,action=''){return `<div class="empty"><h3>${esc(title)}</h3><p>${esc(description)}</p>${action}</div>`;}
function info(text,type=''){return `<div class="info ${type}">${text}</div>`;}
function stat(label,value,note){return `<div class="metric-card"><div class="metric-label">${esc(label)}</div><div class="metric-number">${esc(value)}</div><p>${esc(note)}</p></div>`;}
function filterFor(route){return state.filters[route]||(state.filters[route]={q:'',model:'all',status:'all'});}
function matches(entry,filter){const r=entry.record;if(filter.q&&!JSON.stringify(r).toLowerCase().includes(filter.q.toLowerCase()))return false;if(filter.model!=='all'&&!(r.data.models||[]).includes(filter.model))return false;return filter.status==='all'||r.data.status===filter.status||r.data.outcome===filter.status;}
function filters(route,count,models=true,statusOptions=[]){const f=filterFor(route);return `<div class="filter-bar"><div class="search-field"><input id="search-${route}" data-filter="q" type="search" placeholder="Search ${esc(route==='runs'?'execution records':route)}…" aria-label="Search ${esc(route)}" value="${esc(f.q)}"></div>${models?`<div class="filter-group"><label for="model-filter">Deployment</label><select id="model-filter" data-filter="model"><option value="all">All models</option>${Object.entries(MODEL_NAMES).map(([k,v])=>`<option value="${k}" ${f.model===k?'selected':''}>${esc(v)}</option>`).join('')}</select></div>`:''}${statusOptions.length?`<div class="filter-group"><label for="status-filter">Status</label><select id="status-filter" data-filter="status"><option value="all">All statuses</option>${statusOptions.map(x=>`<option value="${x}" ${f.status===x?'selected':''}>${x.replaceAll('_',' ')}</option>`).join('')}</select></div>`:''}<span class="filter-count">${count} records</span></div>`;}
function renderNav(){let group='';$('#nav').innerHTML=ROUTES.map(([id,title,symbol,section])=>{let head='';if(section!==group){head=`<div class="nav-group-label">${section.toUpperCase()}</div>`;group=section;}const kind={scenarios:'scenario',runs:'execution_run',validations:'validation_run',reports:'report'}[id];return head+`<a class="nav-link ${state.route===id?'active':''}" href="#${id}" ${state.route===id?'aria-current="page"':''}><span class="nav-symbol" aria-hidden="true">${symbol}</span>${esc(title)}${kind?`<span class="nav-count">${records(kind).length}</span>`:''}</a>`;}).join('');}
function render(){const route=ROUTES.find(r=>r[0]===state.route)||ROUTES[0];state.route=route[0];renderNav();$('#breadcrumb-current').textContent=route[1];$('#connection-status').textContent=state.mode==='preview'?'Preview':state.unlocked?'Local service unlocked':'Local service locked';$('#connection-status').classList.toggle('live',state.mode==='service'&&state.unlocked);$('#unlock-button').textContent=state.mode==='preview'?'Local setup':state.unlocked?'Lock service':'Unlock service';$('#storage-label').textContent=state.mode==='preview'?'Browser preview · memory only':'Local SQLite · persistent volume';const bar=$('#mode-bar');bar.classList.toggle('service',state.mode==='service');bar.innerHTML=state.mode==='preview'?'<span><strong>INTERACTIVE PREVIEW</strong> · All inspections and incident records shown are synthetic. Changes stay in this tab.</span><button data-action="setup">Run locally</button>':`<span><strong>LOCAL SERVICE</strong> · ${state.unlocked?'Records persist in your local data volume. Fault execution is not implemented.':'Unlock to read or change the workspace. No AWS connection has been inferred.'}</span><button data-action="setup">Connection setup</button>`;const renderers={overview:overviewPage,connections:connectionsPage,inventory:inventoryPage,scenarios:scenariosPage,runs:runsPage,validations:validationsPage,reports:reportsPage,roadmap:roadmapPage,data:dataPage};$('#main').innerHTML=renderers[state.route]();}
function overviewPage(){const snaps=latestSnapshots(),vals=records('validation_run'),gaps=vals.flatMap(e=>e.record.data.checks||[]).filter(c=>c.outcome==='inconclusive').length;const boundary=panel('Execution boundary','What this build can change',`<div class="boundary-list"><div class="boundary-row"><span>Local records and reports</span>${badge('complete','Enabled')}</div><div class="boundary-row"><span>AWS and runtime resources</span>${badge('draft','Read only')}</div><div class="boundary-row"><span>FIS and local fault execution</span>${badge('not_assessed','Not implemented')}</div></div><p class="boundary-note">A completed collection is not a successful resilience test.</p>`);const modelRows=Object.entries(MODEL_NAMES).filter(([m])=>m!=='shared').map(([m,label])=>{const n=snaps.flatMap(e=>e.record.data.resources).filter(r=>r.model===m).length;return `<tr><td>${esc(label)}</td><td class="right mono">${n||'—'}</td><td>${badge(n?'imported':'not_assessed',n?(state.mode==='preview'?'Example records':'Inventory records'):'Not observed')}</td></tr>`;}).join('');const findings=vals.slice(-3).reverse().map(e=>`<div class="finding"><div class="finding-title">${refButton(e.meta.ref,e.record.title)}${badge(e.record.data.outcome)}</div><p>${(e.record.data.checks||[]).filter(c=>c.outcome!=='pass').map(c=>esc(c.title)+': '+esc(c.outcome)).join(' · ')||'Only the listed assertions were evaluated.'}</p></div>`).join('');return pageHeading('Local-first / inspection and evidence','Validation workspace','Inspect a configured environment, preserve what was observed, and evaluate explicit requirements against recorded evidence.',button('Import bundle','import','',true)+button('Connections →','route','data-route="connections"'))+`<div class="metrics">${stat('Latest environment snapshots',snaps.length,state.mode==='preview'?'Synthetic examples only':'One latest snapshot per connection')}${stat('Scenario revisions',records('scenario').length,'36 research drafts + specified examples')}${stat('Validation records',vals.length,'Not a deployment-wide verdict')}${stat('Missing evidence checks',gaps,'Counted across saved validations')}</div><div class="grid"><section class="goal-panel"><div class="eyebrow">CURRENT GATE</div><h2>Prove collection against a real environment.</h2><p>Confirm the account or runtime, collect the requested scopes, and verify that the snapshot survives restart and backup restore. Then specify an incident test. No operational-readiness claim is established by this workspace yet.</p>${button('Review next deliverable →','route','data-route="roadmap"')}</section>${boundary}</div><div class="pipeline"><a href="#scenarios"><span class="step-label">01 / DEFINE</span><strong>Scenario revisions</strong><small>Requirement, procedure, limits</small></a><a href="#runs"><span class="step-label">02 / RECORD</span><strong>Execution & evidence</strong><small>Exact scope and interval</small></a><a href="#validations"><span class="step-label">03 / EVALUATE</span><strong>Validation runs</strong><small>Pass, fail or inconclusive</small></a><a href="#reports"><span class="step-label">04 / REVIEW</span><strong>Frozen reports</strong><small>Inputs, conclusions and limits</small></a></div><div class="grid">${panel('Deployment coverage','Counts from the latest snapshots; not a completeness claim',`<div class="table-wrap"><table><thead><tr><th>Deployment model</th><th class="right">Resources</th><th>Evidence state</th></tr></thead><tbody>${modelRows}</tbody></table></div>`,button('Inspect inventory','route','data-route="inventory"',true))}<div>${panel('Findings requiring evidence','A failed assertion and absent evidence are different findings',`<div class="findings">${findings||'<div class="finding"><p>No validation has been evaluated. Import a run with evidence, or record an inventory collection check.</p></div>'}</div>`)}<div class="section-gap">${activityPanel(4)}</div></div></div>`;}
function activityPanel(limit){return panel('Workspace activity','Local audit entries; not a tamper-proof audit trail',`<div class="activity">${state.audit.slice(0,limit).map(a=>`<div class="activity-row"><span class="activity-mark"></span><div><strong>${esc(a.action.replaceAll('_',' '))}</strong><p>${esc(a.detail.connection_id||a.detail.note||(a.detail.records?`${a.detail.records.length} record decisions`:a.detail.format||''))}</p></div><time>${esc(shortDate(a.at))}</time></div>`).join('')||'<div class="activity-row"><p>No local activity is loaded.</p></div>'}</div>`);}
function connectionsPage(){const connections=state.connections.length?state.connections:[{id:'unconfigured-aws',name:'AWS account',kind:'aws',unconfigured:true},{id:'unconfigured-docker',name:'Local Docker engine',kind:'docker',unconfigured:true},{id:'unconfigured-podman',name:'Local Podman engine',kind:'podman',unconfigured:true},{id:'unconfigured-kubernetes',name:'Kubernetes namespace',kind:'kubernetes',unconfigured:true}];return pageHeading('Identity / scope / collection','Connections','Connections are named in the administrator configuration. The browser can invoke an allowed inspector, not supply credentials or arbitrary endpoints.',button('Setup instructions','setup','',true))+`<div class="connection-grid">${connections.map(c=>{const snap=latestSnapshots().find(e=>e.record.data.connection_id===c.id);let fields=c.kind==='aws'?[['Expected account',c.expected_account_id||'Not configured'],['Credential source',c.profile||'Backend credential chain'],['Regions',(c.regions||[]).join(', ')||'Not configured'],['Requested services',(c.services||[]).length?c.services.join(', '):'Not configured']]:c.kind==='kubernetes'?[['Context',c.context||(c.in_cluster?'In-cluster service account':'Not configured')],['Namespaces',(c.namespaces||[]).join(', ')||'Not configured'],['Allowed operations','List selected workload metadata'],['Excluded','Secrets, ConfigMaps, logs and exec']]:[['Transport','Administrator-configured Unix socket'],['Allowed requests','Version, containers, volumes, networks'],['Data excluded','Environments, logs and volume content'],['Authority warning','Raw socket access remains privileged']];return `<article class="connection-card"><div class="connection-card-header"><div class="provider-icon ${c.kind}">${c.kind==='kubernetes'?'K8S':c.kind==='docker'?'DCK':c.kind==='podman'?'POD':'AWS'}</div><div><h2>${esc(c.name)}</h2><p>${esc(c.id)}</p></div></div><div class="detail-grid">${fields.map(([k,v])=>`<div class="detail-item"><span class="label">${esc(k)}</span><span class="value">${esc(v)}</span></div>`).join('')}</div>${snap?`<div class="inline-list">${badge(snapshotStatus(snap),'Last collection: '+snapshotStatus(snap))}${originBadge(snap)}</div>`:badge('not_assessed','No collection recorded')}<div class="connection-card-footer"><p>${snap?esc(shortDate(snap.record.data.ended_at)):'Identity has not been verified.'}</p>${c.unconfigured?button('Configure','setup','',true):button(state.mode==='preview'?'View example':'Inspect connection',state.mode==='preview'?'connection-example':'inspect',`data-id="${esc(c.id)}"`,state.mode==='preview')}</div></article>`;}).join('')}</div><div class="section-gap">${info('<strong>Read-only means no write calls in these adapters—not reduced authority of the supplied credential or engine socket.</strong> Use a restricted AWS role and namespace RoleBindings. For Docker or Podman, an administrator-enforced read-only proxy provides a stronger boundary than this process’s request allowlist.','warning')}</div>`;}
function inventoryPage(){const f=filterFor('inventory');const snapshots=state.inventoryRef==='latest'?latestSnapshots():records('snapshot').filter(e=>e.meta.ref===state.inventoryRef);let resources=snapshots.flatMap(e=>e.record.data.resources.map(r=>({resource:r,snapshot:e})));resources=resources.filter(x=>(f.model==='all'||x.resource.model===f.model)&&(!f.q||JSON.stringify(x.resource).toLowerCase().includes(f.q.toLowerCase())));const shown=resources.slice(0,state.inventoryLimit);const cover=snapshots.flatMap(e=>e.record.data.coverage.map(c=>({c,e})));return pageHeading('Bounded collection / explicit gaps','Inventory','A snapshot preserves account identity, collection interval, requested scope and per-scope failures. It does not measure request handling or recovery.',button('Inspect a connection','route','data-route="connections"'))+`<div class="filter-bar"><div class="filter-group"><label for="snapshot-filter">Snapshot</label><select id="snapshot-filter" data-snapshot-select><option value="latest">Latest per connection</option>${records('snapshot').slice().reverse().map(e=>`<option value="${esc(e.meta.ref)}" ${state.inventoryRef===e.meta.ref?'selected':''}>${esc(e.record.title)} · ${esc(shortDate(e.record.data.ended_at))}</option>`).join('')}</select></div><span class="filter-count">${snapshots.length} snapshots selected</span></div>`+filters('inventory',resources.length,true)+(!snapshots.length?empty('No environment has been inspected','Configure a connection and run a read-only inspection, or import a snapshot bundle. Permission failures will appear as collection gaps.',button('Open connections','route','data-route="connections"')):`${panel('Collected resources',`Showing ${shown.length} of ${resources.length} matching resources`, `<div class="table-wrap"><table><thead><tr><th>Resource</th><th>Deployment</th><th>Location</th><th>Observed state</th><th>Source</th></tr></thead><tbody>${shown.map(({resource:r,snapshot:e})=>`<tr><td><button class="text-link cell-title" data-action="resource" data-ref="${esc(e.meta.ref)}" data-id="${esc(r.id)}">${esc(r.name)}</button><span class="cell-sub">${esc(r.kind)}</span></td><td>${esc(MODEL_NAMES[r.model]||r.model)}</td><td class="mono">${esc(r.location)}</td><td>${badge('not_assessed',r.state)}</td><td>${e.record.simulated?badge('simulated','Example'):refButton(e.meta.ref,e.record.data.connection_id)}</td></tr>`).join('')||'<tr><td colspan="5">No resource matches this filter. Check coverage before interpreting an empty inventory.</td></tr>'}</tbody></table></div>${resources.length>shown.length?`<div class="panel-footer">${button('Show 200 more','more-inventory','',true)}</div>`:''}`)}<div class="section-gap">${panel('Collection coverage','An access failure is not evidence that a resource does not exist',`<div class="table-wrap"><table><thead><tr><th>Connection / requested scope</th><th>Result</th><th>Resources</th><th>Collection detail</th></tr></thead><tbody>${cover.map(({c,e})=>`<tr><td>${refButton(e.meta.ref,e.record.data.connection_id)}<span class="cell-sub mono">${esc(c.scope)}</span></td><td>${badge(c.status)}</td><td class="mono">${c.resource_count}</td><td><span class="cell-title">${esc(c.error_code||'No API error recorded')}</span><span class="cell-sub">${esc(c.detail)}</span></td></tr>`).join('')}</tbody></table></div>`)} </div>`);}
function scenariosPage(){const f=filterFor('scenarios');const list=records('scenario').filter(e=>matches(e,f));return pageHeading('Versioned requirements / no executable code','Scenarios','The inherited 36 scenarios remain drafts. A specified record has scalar assertions; it still does not authorize or execute a fault.',button('New definition','new-scenario','',true)+button('Import definitions','import'))+filters('scenarios',list.length,true,['draft','specified'])+panel('Scenario definitions','Every run references a fixed scenario revision',`<div class="table-wrap"><table><thead><tr><th>Scenario</th><th>Deployment</th><th>Domain</th><th>Definition</th><th>Checks</th><th></th></tr></thead><tbody>${list.map(e=>{const r=e.record,d=r.data;return `<tr><td><button class="text-link cell-title" data-action="detail" data-ref="${esc(e.meta.ref)}">${esc(r.title)}</button><span class="cell-sub mono">${esc(r.id)} · rev ${r.revision}${r.simulated?' · SYNTHETIC':''}</span></td><td>${d.models.length>3?`<span class="badge">${d.models.length} models</span>`:tags(d.models)}</td><td>${esc(d.domain)}</td><td>${badge(d.status)}</td><td class="mono">${d.assertions.length||'—'}</td><td class="table-actions"><button class="button compact secondary" data-action="detail" data-ref="${esc(e.meta.ref)}">Inspect</button></td></tr>`;}).join('')||'<tr><td colspan="6">No definitions match this filter.</td></tr>'}</tbody></table></div>`);}
function runsPage(){const f=filterFor('runs');const list=records('execution_run').filter(e=>!f.q||JSON.stringify(e.record).toLowerCase().includes(f.q.toLowerCase())).slice().reverse();return pageHeading('Execution is separate from validation','Execution records','A record describes what was planned or done, where, and when. Imported execution claims remain unverified; this build does not start faults.',button('New plan record','new-run','',true)+button('Import runs & evidence','import'))+filters('runs',list.length,false)+(!list.length?empty('No execution records','Import a completed run and its measurements, or create an observation run from a stored inventory snapshot.',button('View inventory','route','data-route="inventory"')):panel('Recorded executions','A completed execution can still fail validation',`<div class="table-wrap"><table><thead><tr><th>Execution record</th><th>Type / origin</th><th>Execution state</th><th>Interval start</th><th>Evidence</th><th></th></tr></thead><tbody>${list.map(e=>{const r=e.record,d=r.data,n=records('evidence').filter(x=>x.record.data.run_ref===e.meta.ref).length;return `<tr><td>${refButton(e.meta.ref,r.title)}<span class="cell-sub mono">${esc(d.scope_id)}</span></td><td>${badge(d.execution_type)}<span class="cell-sub">${originBadge(e)}</span></td><td>${badge('not_assessed',d.execution_state)}</td><td class="no-wrap">${esc(shortDate(d.started_at))}</td><td class="mono">${n}</td><td class="table-actions">${button('Evaluate','evaluate',`data-ref="${esc(e.meta.ref)}"`,true)}</td></tr>`;}).join('')}</tbody></table></div>`));}
function validationsPage(){const f=filterFor('validations'),list=records('validation_run').filter(e=>matches(e,f)).slice().reverse();return pageHeading('Pinned inputs / reproducible comparisons','Validation runs','Evaluate supplied evidence against the exact scenario revision. Missing measurements, wrong units and incomplete windows cannot satisfy a required check.',button('Import validation records','import','',true))+filters('validations',list.length,false,['pass','fail','inconclusive','not_assessed'])+(!list.length?empty('No validation has been evaluated','Select an execution record and evaluate it. Each evaluation creates a new immutable validation record.',button('Open execution records','route','data-route="runs"')):panel('Evaluation history','Imported verdicts are displayed as claims until recomputed here',`<div class="table-wrap"><table><thead><tr><th>Validation</th><th>Outcome</th><th>Checks</th><th>Evaluation time</th><th>Trust boundary</th><th></th></tr></thead><tbody>${list.map(e=>{const r=e.record,d=r.data;return `<tr><td>${refButton(e.meta.ref,r.title)}<span class="cell-sub mono">${esc(d.run_ref)}</span></td><td>${badge(d.outcome)}</td><td class="mono">${d.checks.filter(c=>c.outcome==='pass').length} / ${d.checks.length} passed</td><td class="no-wrap">${esc(shortDate(d.evaluated_at))}</td><td>${originBadge(e)}</td><td>${button('Inspect','detail',`data-ref="${esc(e.meta.ref)}"`,true)}</td></tr>`;}).join('')}</tbody></table></div>`));}
function reportsPage(){const list=records('report').slice().reverse();return pageHeading('Frozen conclusions / explicit limitations','Reports','A report references a validation result rather than a live dashboard. Imported report text is inert; it is never executed or treated as independently verified.',button('Import reports','import','',true))+(!list.length?empty('No reports have been created','Open a validation run and create a report. Export its referenced records to preserve the evidence path.',button('Open validations','route','data-route="validations"')):`<div class="report-grid">${list.map(e=>{const r=e.record,d=r.data;return `<article class="report-card"><div class="inline-list">${badge(d.outcome)}${originBadge(e)}</div><h2>${esc(r.title)}</h2><p>${esc(d.body.slice(0,220))}${d.body.length>220?'…':''}</p><p class="small-note">${esc(shortDate(d.generated_at))}<br>${esc(d.validation_ref||'No linked validation record')}</p><div class="inline-list">${button('Open report','detail',`data-ref="${esc(e.meta.ref)}"`)}${button('Export bundle','export-record',`data-ref="${esc(e.meta.ref)}"`,true)}</div></article>`;}).join('')}</div>`);}
function roadmapPage(){return pageHeading('Reanchored baseline / value-ranked delivery','Goal & roadmap','Goal: measure customer impact, detection, response and stable recovery during bounded incidents—not simply whether a fault API completed.')+`<div class="grid equal">${panel('Context retained','The research remains useful, but it is not proof of readiness',`<div class="panel-body text-block"><p>The scope includes EC2/Auto Scaling, EKS on EC2, EKS on Fargate, ECS on EC2, ECS on Fargate and Lambda, plus shared AWS dependencies and local Docker, Podman and Kubernetes environments.</p><p>The revised report supplied 36 scenario descriptions and six FIS template starters. They have not been executed against your infrastructure. The console imports the scenarios as drafts, without inventing acceptance limits.</p></div>`)}${panel('Progress at this handoff','Artifacts, implementation and field acceptance are distinct',`<div class="table-wrap"><table class="progress-table"><tbody><tr><td>Research catalogue</td><td>${badge('complete','Available')}</td></tr><tr><td>Local console and typed records</td><td>${badge('complete','Code delivered')}</td></tr><tr><td>Read-only connector acceptance</td><td>${badge('inconclusive','Real environment pending')}</td></tr><tr><td>Fault execution and incident telemetry</td><td>${badge('not_assessed','Not implemented')}</td></tr><tr><td>Deployment readiness</td><td>${badge('not_assessed','Not established')}</td></tr></tbody></table></div>`)}</div><h2 class="section-title">Next items, ordered by decision value</h2><p class="subtle">The order removes false-confidence risks before adding automation. It is a dependency-aware product priority, not an estimated financial ROI.</p><div class="panel section-gap">${APP_DATA.roadmap.map(r=>`<article class="roadmap-card"><div class="rank">${String(r.rank).padStart(2,'0')}</div><div><div class="roadmap-title"><h2>${esc(r.title)}</h2>${badge(r.rank<4?'inconclusive':'not_assessed',r.status)}</div><p>${esc(r.value)}</p><details ${r.rank===1?'open':''}><summary>Deliverable and acceptance gate</summary><dl><dt>Deliverable</dt><dd>${esc(r.deliverable)}</dd><dt>Exit condition</dt><dd>${esc(r.exit)}</dd><dt>Dependency</dt><dd>${esc(r.depends)}</dd></dl></details></div></article>`).join('')}</div>`;}
function dataPage(){return pageHeading('Local ownership / import and restore','Data & security','The service stores records in local SQLite. The preview stores changes only in this tab. Neither mode uploads workspace data to a hosted service.',button('Import bundle','import','',true)+button('Export workspace','export'))+`<div class="grid equal">${panel('Workspace storage','SQLite is the source of truth in local-service mode',`<div class="panel-body"><div class="detail-grid"><div class="detail-item"><span class="label">Current mode</span><span class="value">${state.mode==='preview'?'Preview · transient browser memory':'Local service · persistent SQLite'}</span></div><div class="detail-item"><span class="label">Stored records</span><span class="value mono-value">${state.entries.length}</span></div><div class="detail-item"><span class="label">Database path</span><span class="value mono">CONSOLE_DATA/workspace.sqlite3</span></div><div class="detail-item"><span class="label">Write semantics</span><span class="value">Append new records or revisions; no overwrite API.</span></div></div><div class="settings-actions">${button('Export JSON bundle','export','',true)}${button('Download SQLite backup','backup','',true)}</div><p class="small-note">JSON imports reset source trust to imported. A database backup preserves local provenance and audit records. Stop the service before restoring the database. A checksum is not a signature.</p></div>`)}${panel('Runtime and credentials','Administrative setup stays outside the browser',`<div class="panel-body"><div class="step-list"><div class="step-item"><p>Run one service instance in Docker, Podman or a local Kubernetes cluster. Mount a persistent data volume.</p></div><div class="step-item"><p>Configure named AWS profiles and exact account IDs, or approved local sockets and Kubernetes contexts.</p></div><div class="step-item"><p>Unlock this page with the console token. It is held in memory, not saved in browser storage.</p></div></div><div class="settings-actions">${button('Open setup guide','setup','',true)}${button('View example config','config-example','',true)}</div></div>`)}</div><div class="section-gap">${info('<strong>Do not mount an engine socket and call the mount “read only.”</strong> A read-only filesystem mount does not make the API read-only. This build uses a fixed GET allowlist, but the process still holds socket authority. Network exposure, stronger runtime isolation and multi-user approvals require additional controls.','warning')}</div><h2 class="section-title">Interchange records</h2>${panel('Version 1 JSON bundles','Unknown fields and broken references are rejected by the local service',`<div class="table-wrap"><table><thead><tr><th>Record kind</th><th>Purpose</th><th>What it does not establish</th></tr></thead><tbody><tr><td class="mono">scenario</td><td>Versioned requirement, procedure and assertions</td><td>Permission or approval to execute a fault</td></tr><tr><td class="mono">execution_run</td><td>Scope, interval and claimed execution state</td><td>That the workload passed its requirements</td></tr><tr><td class="mono">snapshot / evidence</td><td>Collected configuration or scalar measurements</td><td>Source authenticity merely because the file loaded</td></tr><tr><td class="mono">validation_run</td><td>Check outcomes pinned to input hashes</td><td>Untested requirements or broader deployment readiness</td></tr><tr><td class="mono">report</td><td>Frozen conclusion and limitations</td><td>Live health or independent certification</td></tr></tbody></table></div><div class="panel-footer">5 MiB per import · JSON only · no shell commands or arbitrary evaluator expressions</div>`)}<div class="grid equal section-gap">${activityPanel(10)}${panel('Primary-source design references','Reviewed 21 October 2026; scenario-level references stay with each definition',`<div class="panel-body"><ul class="source-list">${APP_DATA.sources.map(s=>`<li><a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)} ↗</a><p>${esc(s.supports)}</p></li>`).join('')}</ul></div>`)}</div>`;}
function openModal(title,description,body,footer=''){const d=$('#modal');$('#modal-content').innerHTML=`<div class="dialog-header"><div><h2>${esc(title)}</h2><p>${esc(description)}</p></div><button class="icon-button" data-action="close-modal" aria-label="Close dialog">×</button></div><div class="dialog-body">${body}</div>${footer?`<div class="dialog-footer">${footer}</div>`:''}`;if(!d.open)d.showModal();}
function closeModal(){$('#modal').close();}
function showDrawer(title,subtitle,body){$('#drawer-content').innerHTML=`<div class="dialog-header"><div><h2>${esc(title)}</h2><p>${esc(subtitle)}</p></div><button class="icon-button" data-action="close-drawer" aria-label="Close record details">×</button></div><div class="dialog-body">${body}</div>`;if(!$('#drawer').open)$('#drawer').showModal();}
function section(title,content){return `<section class="record-section"><h3>${esc(title)}</h3>${content}</section>`;}
function safeLink(url){try{const u=new URL(url);return u.protocol==='https:'?`<a href="${esc(u.href)}" target="_blank" rel="noopener noreferrer">${esc(u.hostname+u.pathname)} ↗</a>`:esc(url);}catch(_){return esc(url);}}
function showDetail(reference){const e=get(reference);if(!e){toast('That record is not loaded.',true);return;}const r=e.record,d=r.data;let body=`<div class="inline-list">${badge(r.kind)}${originBadge(e)}${d.status?badge(d.status):''}${d.outcome?badge(d.outcome):''}</div>`;if(r.simulated)body+=`<div class="section-gap">${info('<strong>Synthetic fixture.</strong> No AWS account, runtime, application or responder was tested.','warning')}</div>`;if(e.meta.origin==='imported')body+=`<div class="section-gap">${info('Imported content is not independently verified. Recompute a validation from its inputs before relying on a claimed result.','warning')}</div>`;body+=`<div class="drawer-actions">${button('Export with references','export-record',`data-ref="${esc(reference)}"`,true)}${button('Copy reference','copy',`data-value="${esc(reference)}"`,true)}</div>`;
 if(r.kind==='scenario'){body+=section('Deployment and definition',`<div class="inline-list">${tags(d.models)}</div><p class="small-note">${esc(d.domain)} · ${esc(d.fault_mode)} fault mode · ${d.assertions.length} scalar checks</p>`)+section('Requirement',`<p>${esc(d.hypothesis)}</p>`)+section('Procedure',`<p>${esc(d.procedure)}</p>`)+section('Proposed action',`<pre>${esc(d.action||'No fault injection')}</pre>`)+section('Required evidence',`<ul>${d.evidence_required.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`)+section('Acceptance',`<p>${esc(d.acceptance||'Not specified')}</p>`);if(d.assertions.length)body+=section('Machine-evaluable assertions',d.assertions.map(a=>`<div class="check-card"><div class="check-heading"><h3>${esc(a.title)}</h3>${badge(a.category)}</div><div class="check-values"><span>${esc(a.metric)}</span><span>${esc(a.operator)} ${esc(a.threshold)} ${esc(a.unit)}</span></div><p>Minimum samples: ${a.min_samples}. Maximum collection lag: ${a.max_collection_lag_seconds} seconds. ${a.required?'Required':'Optional'}.</p></div>`).join(''));else body+=info('No machine-evaluable assertions. This definition cannot produce a passing validation until its limits and evidence requirements are specified.','warning');body+=section('Recovery check',`<p>${esc(d.recovery||'Not specified')}</p>`)+`<div class="drawer-actions">${button('Create next revision','revise',`data-ref="${esc(reference)}"`,true)}${button('Create plan record','new-run',`data-ref="${esc(reference)}"`)}</div>`;}
 if(r.kind==='execution_run'){const ev=records('evidence').filter(x=>x.record.data.run_ref===reference);body+=section('Execution scope',`<div class="detail-grid"><div class="detail-item"><span class="label">Scenario revision</span>${refButton(d.scenario_ref)}</div><div class="detail-item"><span class="label">Execution state</span>${badge('not_assessed',d.execution_state)}</div><div class="detail-item"><span class="label">Scope</span><span class="value mono">${esc(d.scope_id)}</span></div><div class="detail-item"><span class="label">Fault confirmed</span><span class="value">${d.fault_confirmed===true?'Recorded as confirmed':d.fault_confirmed===false?'Recorded as not confirmed':'Not recorded / not applicable'}</span></div><div class="detail-item"><span class="label">Started</span>${esc(shortDate(d.started_at))}</div><div class="detail-item"><span class="label">Ended</span>${esc(shortDate(d.ended_at))}</div></div>`)+section('Run notes',`<p>${esc(d.notes||'No notes supplied.')}</p>`)+section('Linked evidence',ev.length?`<div class="table-wrap"><table><thead><tr><th>Metric</th><th>Value</th><th>Samples</th></tr></thead><tbody>${ev.map(x=>`<tr><td>${refButton(x.meta.ref,x.record.data.metric)}</td><td class="mono">${esc(x.record.data.value)} ${esc(x.record.data.unit)}</td><td class="mono">${x.record.data.sample_count}</td></tr>`).join('')}</tbody></table></div>`:info('No evidence record is linked to this run. Required assertions will be inconclusive.','warning'))+`<div class="drawer-actions">${button('Evaluate recorded evidence','evaluate',`data-ref="${esc(reference)}"`)}${button('Import more evidence','import','',true)}</div>`;}
 if(r.kind==='validation_run'){body+=section('Pinned inputs',`<div class="detail-grid"><div class="detail-item"><span class="label">Execution record</span>${refButton(d.run_ref)}</div><div class="detail-item"><span class="label">Scenario revision</span>${refButton(d.scenario_ref)}</div><div class="detail-item"><span class="label">Evaluator</span><span class="mono">${esc(d.evaluator_version)}</span></div><div class="detail-item"><span class="label">Evaluated</span>${esc(shortDate(d.evaluated_at))}</div></div>`);if(d.gates.length)body+=section('Assessment gates',info(d.gates.map(esc).join('<br>'),'warning'));body+=section('Assertion outcomes',d.checks.map(c=>`<div class="check-card"><div class="check-heading"><h3>${esc(c.title)}</h3>${badge(c.outcome)}</div><div class="check-values"><span>Expected: ${esc(c.expected)}</span><span>Observed: ${c.observed===null?'not supplied':esc(c.observed)}</span></div><p>${esc(c.reason)}</p><p class="subtle">${esc(c.category)} · ${c.required?'required':'optional'}${c.evidence_ref?' · '+refButton(c.evidence_ref):''}</p></div>`).join('')||'<p>No assertions were evaluated.</p>')+`<div class="drawer-actions">${button('Create report','report',`data-ref="${esc(reference)}"`)}${button('Recompute from run','evaluate',`data-ref="${esc(d.run_ref)}"`,true)}</div>`+section('Input content hashes',`<div class="table-wrap"><table><thead><tr><th>Input</th><th>SHA-256</th></tr></thead><tbody>${Object.entries(d.input_hashes).map(([k,v])=>`<tr><td>${refButton(k)}</td><td class="hash">${esc(v)}</td></tr>`).join('')}</tbody></table></div>`);}
 if(r.kind==='snapshot'){body+=section('Collection identity',`<pre>${esc(JSON.stringify(d.identity,null,2))}</pre>`)+section('Collection interval',`<p>${esc(shortDate(d.started_at))} → ${esc(shortDate(d.ended_at))}</p><p class="small-note">${esc(d.scope_id)}</p>`)+section('Coverage',d.coverage.map(c=>`<div class="check-card"><div class="check-heading"><h3>${esc(c.scope)}</h3>${badge(c.status)}</div><p class="small-note">${esc(c.detail)} ${esc(c.error_code)}</p></div>`).join(''))+`<div class="drawer-actions">${button('View resources','snapshot-inventory',`data-ref="${esc(reference)}"`,true)}${button('Record collection check','observe',`data-ref="${esc(reference)}" ${r.simulated?'disabled':''}`)}</div>`+info('A collection check scores whether the requested reads completed. It makes no statement about application behavior during an incident.');}
 if(r.kind==='evidence'){body+=section('Measurement',`<div class="detail-grid"><div class="detail-item"><span class="label">Metric</span><span class="value mono">${esc(d.metric)}</span></div><div class="detail-item"><span class="label">Observed</span><span class="value mono">${esc(d.value)} ${esc(d.unit)}</span></div><div class="detail-item"><span class="label">Samples</span>${d.sample_count}</div><div class="detail-item"><span class="label">Run</span>${refButton(d.run_ref)}</div></div>`)+section('Measurement window',`<p>${esc(shortDate(d.window_start))} → ${esc(shortDate(d.window_end))}</p><p class="small-note">Collected: ${esc(shortDate(d.collected_at))}</p>`)+section('Scope and source',`<pre>${esc(d.scope_id)}\n${esc(d.source)}</pre>`)+section('Notes',`<p>${esc(d.notes)}</p>`);}
 if(r.kind==='report'){body+=section('Frozen report',`<pre>${esc(d.body)}</pre>`)+section('Referenced validation',d.validation_ref?refButton(d.validation_ref):'<p>No linked validation. This is an imported standalone report.</p>')+`<div class="drawer-actions">${button('Download HTML report','download-report',`data-ref="${esc(reference)}"`)}${button('Export report bundle','export-record',`data-ref="${esc(reference)}"`,true)}</div>`;}
 if(d.limitations&&d.limitations.length)body+=section('Limits of this record',`<ul>${d.limitations.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`);if(d.source_urls&&d.source_urls.length)body+=section('Definition references',`<ul>${d.source_urls.map(x=>`<li>${safeLink(x)}</li>`).join('')}</ul>`);body+=section('Record integrity',`<p class="hash">${esc(e.meta.sha256)}</p><p class="small-note">SHA-256 of normalized record content. This does not authenticate the original producer.</p>`)+section('Source record',`<details><summary>Inspect versioned JSON</summary><pre>${esc(JSON.stringify(r,null,2))}</pre></details>`);showDrawer(r.title,reference,body);}
function showResource(reference,id){const e=get(reference);const r=e?.record.data.resources.find(x=>x.id===id);if(!r)return;showDrawer(r.name,r.kind,`<div class="inline-list">${badge('not_assessed',r.state)}${badge('not_assessed',MODEL_NAMES[r.model])}${originBadge(e)}</div>${section('Resource identity',`<pre>${esc(r.id)}</pre>`)}${section('Location',`<p>${esc(r.location)}</p>`)}${section('Allowlisted facts',`<pre>${esc(JSON.stringify(r.facts,null,2))}</pre>`)}${section('Collection snapshot',refButton(reference,e.record.title))}${info('These are configuration or runtime-status observations, not incident-response measurements.')}`);}
function openImport(initial){state.importReviewed=false;state.importRaw='';const text=initial?JSON.stringify(initial,null,2):'';openModal('Import versioned records','Review the bundle before committing. Existing records cannot be overwritten.',`<div class="import-toolbar"><label for="json-file">Load a JSON file</label><input id="json-file" type="file" accept=".json,application/json"><button class="button compact secondary" data-action="load-example">Use synthetic workflow</button><button class="button compact secondary" data-action="load-catalogue">Use scenario catalogue</button></div><label class="subtle" for="import-json">Version 1 bundle · maximum 5 MiB · no credentials or kubeconfig</label><textarea id="import-json" class="json-editor" spellcheck="false" placeholder='{"schema_version":"1.0","kind":"validation_bundle","records":[…]}'>${esc(text)}</textarea><div id="import-review" class="import-review">${state.mode==='preview'?info('Preview imports check JSON structure and references only. The local service enforces the complete schema; preview imports are not authoritative.','warning'):''}</div>`,button('Review import','review-import','',true)+button(state.mode==='preview'?'Add to preview':'Commit import','commit-import','id="commit-import" disabled'));}
function basicReview(bundle){if(!bundle||bundle.schema_version!=='1.0'||bundle.kind!=='validation_bundle'||!Array.isArray(bundle.records)||!bundle.records.length)throw new Error('Expected a version 1 validation_bundle with a non-empty records array.');if(bundle.records.length>5000)throw new Error('A bundle may contain at most 5,000 records.');const supported=['scenario','execution_run','snapshot','evidence','validation_run','report'];const map=new Map(state.entries.map(e=>[e.meta.ref,e.record]));const incoming=new Set();for(const r of bundle.records){if(!supported.includes(r.kind)||!/^[A-Za-z0-9][A-Za-z0-9_.-]{0,99}$/.test(r.id||'')||!Number.isInteger(r.revision)||r.revision<1||typeof r.title!=='string'||!r.data||typeof r.simulated!=='boolean')throw new Error('Invalid record identity, kind, title, simulation label or data. Use the supplied schema.');const key=rid(r);if(incoming.has(key))throw new Error('Duplicate reference in this bundle: '+key);incoming.add(key);const previous=map.get(key);if(previous&&stable(previous)!==stable(r))throw new Error('Immutable reference conflicts: '+key+'. Use a new revision.');if(r.kind==='scenario'&&(!Array.isArray(r.data.models)||!Array.isArray(r.data.assertions)||!['draft','specified'].includes(r.data.status)))throw new Error('Scenario models, assertions and status are required.');if(r.kind==='validation_run'&&(!Array.isArray(r.data.checks)||!Array.isArray(r.data.gates)||!r.data.input_hashes))throw new Error('Validation checks, gates and input hashes are required.');if(r.kind==='snapshot'&&(!Array.isArray(r.data.resources)||!Array.isArray(r.data.coverage)))throw new Error('Snapshot resources and coverage must be arrays.');if(r.kind==='report'&&(typeof r.data.body!=='string'||!Array.isArray(r.data.limitations)))throw new Error('Report body and limitations are required.');map.set(key,r);}for(const r of bundle.records)for(const k of ['scenario_ref','run_ref','snapshot_ref','validation_ref'])if(r.data[k]&&!map.has(r.data[k]))throw new Error('Missing reference: '+r.data[k]+'. Include it or import it first.');return {decisions:bundle.records.map(r=>({ref:rid(r),action:get(rid(r))?'unchanged':'create'})),created:bundle.records.filter(r=>!get(rid(r))).length,committed:false};}
async function reviewImport(){const text=$('#import-json').value;if(new TextEncoder().encode(text).length>5*1024*1024)throw new Error('Import exceeds 5 MiB.');state.importReviewed=false;$('#commit-import').disabled=true;try{const b=JSON.parse(text);const result=state.mode==='service'?await api('import/preview',{method:'POST',body:text,raw:true}):basicReview(b);state.importRaw=text;state.importReviewed=true;$('#import-review').innerHTML=info(`${result.created} new records. ${result.decisions.length-result.created} unchanged records. Nothing has been committed.`)+`<div class="table-wrap"><table><thead><tr><th>Reference</th><th>Decision</th></tr></thead><tbody>${result.decisions.map(d=>`<tr><td class="mono">${esc(d.ref)}</td><td>${badge(d.action==='create'?'complete':'not_assessed',d.action)}</td></tr>`).join('')}</tbody></table></div>`+(state.mode==='preview'?'<p class="small-note">Preview review is not full schema validation. Commit to the local service for authoritative validation.</p>':'');$('#commit-import').disabled=false;}catch(err){$('#import-review').innerHTML=`<div class="import-errors">${esc(err.message)}</div>`;throw err;}}
async function addPreview(recordsToAdd,origin='imported'){const decisions=[];for(const record of recordsToAdd){const reference=rid(record);if(get(reference)){decisions.push({ref:reference,action:'unchanged'});continue;}state.entries.push({record:clone(record),meta:{ref:reference,sha256:await hash(record),origin,created_at:now()}});decisions.push({ref:reference,action:'create'});}state.audit.unshift({seq:state.audit.length+1,at:now(),action:origin,detail:{records:decisions}});render();}
async function commitImport(){if(!state.importReviewed||state.importRaw!==$('#import-json').value)throw new Error('Review the current text before committing.');if(state.mode==='service'){await api('import',{method:'POST',body:state.importRaw,raw:true});await refresh();}else{const bundle=JSON.parse(state.importRaw);basicReview(bundle);await addPreview(bundle.records,'imported');}closeModal();toast(state.mode==='preview'?'Records added to this preview tab only.':'Import committed to the local database.');}
function newScenario(){const r={kind:'scenario',id:'new-scenario-'+Date.now(),revision:1,title:'New incident requirement',simulated:false,data:{status:'draft',models:['ec2'],domain:'To be specified',hypothesis:'Specify the behavior that must hold during the incident.',procedure:'Specify exact targets, controlled workload, fault and recovery steps.',fault_mode:'external',action:'',evidence_required:[],acceptance:'Set service-owned limits, measurement windows and sample requirements.',recovery:'Specify cleanup and a post-recovery transaction check.',limitations:[],source_urls:[],assertions:[]}};openImport({schema_version:'1.0',kind:'validation_bundle',records:[r]});}
function newRun(scenarioRef){const s=scenarioRef?get(scenarioRef):records('scenario').find(e=>!e.record.simulated);if(!s)throw new Error('Import a scenario before creating a plan record.');const r={kind:'execution_run',id:'plan-'+Date.now(),revision:1,title:'Plan · '+s.record.title,simulated:s.record.simulated,data:{scenario_ref:s.meta.ref,snapshot_ref:null,execution_type:s.record.simulated?'simulated':'external',execution_state:'planned',scope_id:'UNRESOLVED-scope',targets:[],started_at:now(),ended_at:null,fault_confirmed:null,external_id:null,notes:'Plan record only. No fault is executed by this console. Replace the scope and dates before recording a completed execution.'}};openImport({schema_version:'1.0',kind:'validation_bundle',records:[r]});}
function aggregate(outcomes){if(outcomes.includes('fail'))return 'fail';if(!outcomes.length||outcomes.includes('inconclusive'))return 'inconclusive';if(outcomes.every(o=>o==='not_assessed'))return 'not_assessed';return 'pass';}
async function evaluatePreview(runRef){const re=get(runRef);if(!re||re.record.kind!=='execution_run')throw new Error('Execution record not found.');const run=re.record,d=run.data,se=get(d.scenario_ref);if(!se)throw new Error('Scenario revision is missing.');const s=se.record.data,ev=records('evidence').filter(e=>e.record.data.run_ref===runRef);const gates=[];if(d.ended_at&&Date.parse(d.ended_at)>Date.now())gates.push('The completed run ends in the future relative to the evaluator clock.');if(d.execution_state!=='completed')gates.push('Execution is not recorded as completed.');if(!s.assertions.length)gates.push('The scenario has no machine-evaluable assertions. Narrative acceptance criteria were not scored.');if(s.status!=='specified')gates.push('The scenario is a draft.');if(s.fault_mode!=='none'&&d.fault_confirmed!==true)gates.push('Fault application has not been confirmed.');if(run.simulated!==se.record.simulated)gates.push('The run and scenario have inconsistent simulation labels.');const checks=s.assertions.map(a=>{const candidates=ev.filter(e=>e.record.data.metric===a.metric);const out={assertion_id:a.id,title:a.title,category:a.category,required:a.required,outcome:'inconclusive',reason:'',expected:`${a.operator} ${a.threshold} ${a.unit}; at least ${a.min_samples} samples`,observed:null,evidence_ref:null};if(candidates.length!==1){out.reason=candidates.length?'More than one evidence record for this metric. Select one explicitly; windows are not merged.':'No evidence for this metric.';return out;}const entry=candidates[0],e=entry.record.data;out.evidence_ref=entry.meta.ref;out.observed=e.value;const invalid=[];if(entry.record.simulated!==run.simulated)invalid.push('Simulation labels differ');if(e.scope_id!==d.scope_id)invalid.push('Scope differs from the run');if(e.unit!==a.unit)invalid.push('Unit mismatch; no implicit conversion');if(e.sample_count<a.min_samples)invalid.push('Insufficient samples');if((typeof e.value==='boolean')!==(typeof a.threshold==='boolean'))invalid.push('Boolean/numeric type mismatch');if(!['boolean','number'].includes(typeof e.value)||!['boolean','number'].includes(typeof a.threshold))invalid.push('Unsupported value type');const ws=Date.parse(e.window_start),we=Date.parse(e.window_end),rs=Date.parse(d.started_at),rr=d.ended_at?Date.parse(d.ended_at):null,ct=Date.parse(e.collected_at);if([ws,we,rs,ct].some(n=>!Number.isFinite(n)))invalid.push('Invalid timestamp');if(ws>rs||(rr!==null&&we<rr))invalid.push('Evidence does not cover the complete run interval');if(ws<rs||(rr!==null&&we>rr))invalid.push('Evidence includes observations outside the declared run interval');if(ct>Date.now())invalid.push('Evidence collection timestamp is in the future');if((ct-we)/1000>a.max_collection_lag_seconds)invalid.push('Evidence was collected after its permitted lag');if(ct<we||we<ws)invalid.push('Evidence chronology is invalid');if(invalid.length){out.reason=invalid.join('; ')+'.';return out;}const pass=a.operator==='lte'?e.value<=a.threshold:a.operator==='gte'?e.value>=a.threshold:e.value===a.threshold;out.outcome=pass?'pass':'fail';out.reason=pass?'The supplied value satisfies the assertion.':'The supplied value exceeds or differs from the accepted limit.';return out;});const hashes={};[re,se,...ev].forEach(e=>hashes[e.meta.ref]=e.meta.sha256);if(d.snapshot_ref&&get(d.snapshot_ref))hashes[d.snapshot_ref]=get(d.snapshot_ref).meta.sha256;return {kind:'validation_run',id:'preview-val-'+Date.now(),revision:1,title:'Validation · '+run.title,simulated:run.simulated,data:{run_ref:runRef,scenario_ref:d.scenario_ref,evaluator_version:'browser-preview-1.1',evaluated_at:now(),outcome:aggregate(checks.filter(c=>c.required).map(c=>c.outcome))==='fail'?'fail':gates.length?'inconclusive':aggregate(checks.filter(c=>c.required).map(c=>c.outcome)),checks,gates,input_hashes:hashes,limitations:['Browser preview result. Recompute using the local service before relying on imported data.','This result covers only the declared assertions and interval; it is not a deployment-readiness certificate.','Scalar measurements are supplied by the importer; raw telemetry is not reconstructed.',...(run.simulated?['SIMULATED DATA. No deployment was assessed.']:[])]}};}
async function evaluateRun(reference){let entry;if(state.mode==='service'){entry=await api('evaluate',{method:'POST',body:{run_ref:reference}});await refresh();}else{const r=await evaluatePreview(reference);await addPreview([r],'evaluated');entry=get(rid(r));}location.hash='validations';showDetail(entry.meta.ref);toast('New validation saved. The execution record was not changed.');}
async function makeReport(reference){let entry;if(state.mode==='service'){entry=await api('reports',{method:'POST',body:{validation_ref:reference}});await refresh();}else{const e=get(reference),v=e.record,d=v.data;const r={kind:'report',id:'preview-report-'+Date.now(),revision:1,title:v.title.replace('Validation · ','Report · '),simulated:v.simulated,data:{validation_ref:reference,outcome:d.outcome,body:[`Result: ${d.outcome}`,`Execution: ${d.run_ref}`,`Scenario: ${d.scenario_ref}`,'',...d.checks.map(c=>`${c.outcome.toUpperCase()} | ${c.title} | ${c.reason}`),...d.gates.map(g=>'Gate: '+g)].join('\n'),limitations:[...d.limitations,...(e.meta.origin!=='evaluated'?['The validation was imported or supplied as an example; it has not been recomputed here.']:[])],generated_at:now()}};await addPreview([r],'reported');entry=get(rid(r));}location.hash='reports';showDetail(entry.meta.ref);toast('Report created from the saved validation.');}
function lineage(reference){const seen=new Set();function visit(k){if(seen.has(k))return;const e=get(k);if(!e)return;seen.add(k);const d=e.record.data;for(const f of ['scenario_ref','run_ref','snapshot_ref','validation_ref'])if(d[f])visit(d[f]);Object.keys(d.input_hashes||{}).forEach(visit);}visit(reference);const entries=Array.from(seen).map(get);return {schema_version:'1.0',kind:'validation_bundle',records:entries.map(e=>e.record)};}
async function exportWorkspace(){if(state.mode==='service'){download('validation-workspace.json',await api('export',{blob:true}));}else{download('validation-preview.json',JSON.stringify({schema_version:'1.0',kind:'validation_bundle',records:state.entries.map(e=>e.record)},null,2));}toast('Export contains workspace records. Credentials are not part of the record schema.');}
async function downloadReport(reference){const e=get(reference);if(state.mode==='service'){download(e.record.id+'.html',await api('report-html?reference='+encodeURIComponent(reference),{blob:true}),'text/html');}else{const r=e.record,d=r.data;const body=`<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>${esc(r.title)}</title><body><h1>${esc(r.title)}</h1><p><strong>${r.simulated?'SYNTHETIC EXAMPLE — NO DEPLOYMENT ASSESSED':'BROWSER PREVIEW — RECOMPUTE IN THE LOCAL SERVICE'}</strong></p><p>${esc(reference)}</p><pre>${esc(d.body)}</pre><h2>Limitations</h2><ul>${d.limitations.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></body></html>`;download(r.id+'.html',body,'text/html');}}
function setup(){openModal('Run the local validation console','The HTML preview cannot access AWS credentials or runtime sockets. The local service provides those adapters.',`<div class="step-list"><div class="step-item"><p>Unpack the application bundle. It contains the service, this interface, schemas, examples, tests and deployment files.</p></div><div class="step-item"><p>Start with an empty connection list. Run the service and unlock it with the startup token.</p></div><div class="step-item"><p>Add one administrator-approved connection to <code>config.json</code>, then restart. For AWS, supply an exact expected account ID and a restricted profile. For runtimes, configure a socket or namespace explicitly.</p></div></div><h3 class="section-title">Docker</h3><pre class="code-box">docker compose up --build\n# Open http://127.0.0.1:8787\n# Read the private unlock token from the service log.</pre><h3 class="section-title">Python on the local host</h3><pre class="code-box">python -m venv .venv\n. .venv/bin/activate\npip install -r requirements.txt\nexport CONSOLE_CONFIG=./config.json\npython run.py</pre><p class="small-note">The bundle also contains Podman instructions and a single-replica Kubernetes deployment with a persistent volume. Images and Python packages must be obtained before disconnected operation. AWS inspection still needs AWS API connectivity.</p><div class="section-gap">${info('No engine socket, AWS credential directory or kubeconfig is mounted by the default Compose file. Add only the connection access you intend to grant.','warning')}</div>`,button('Close','close-modal','',true));}
function configExample(){const example={connections:[{id:'aws-staging',name:'AWS staging',kind:'aws',profile:'readiness-readonly',expected_account_id:'123456789012',regions:['eu-central-1'],services:['ec2','autoscaling','eks','ecs','lambda','rds','elbv2','cloudwatch','fis']},{id:'docker-local',name:'Local Docker',kind:'docker',socket:'/var/run/docker.sock'},{id:'podman-local',name:'Local Podman',kind:'podman',socket:'/run/user/1000/podman/podman.sock'},{id:'kubernetes-local',name:'Local Kubernetes',kind:'kubernetes',in_cluster:false,kubeconfig:'/home/operator/.kube/config',context:'kind-local',namespaces:['default']}]};openModal('Administrator connection example','Replace the account ID, profile, paths, context and namespaces. Do not paste access keys into this file.',`<pre class="code-box">${esc(JSON.stringify(example,null,2))}</pre><p class="small-note">The browser cannot edit these connection settings. Runtime paths refer to the service process’s filesystem, not necessarily the host path. The AWS profile may assume a restricted role through the SDK credential chain.</p>`,button('Close','close-modal','',true));}
function unlock(){if(state.mode==='preview'){setup();return;}if(state.unlocked){state.token='';state.unlocked=false;state.entries=[];state.audit=[];state.connections=[];$('#drawer').close();render();toast('Service locked. The token was removed from page memory.');return;}openModal('Unlock the local service','Use the console token printed at startup. This is not an AWS access key.',`<form id="unlock-form"><div class="form-field"><label for="console-token">Console token</label><input id="console-token" name="token" type="password" minlength="32" autocomplete="off" spellcheck="false" required><p>The token is kept in this page’s memory. Reloading or locking removes it.</p></div><div class="info">AWS authentication happens on the server using its configured credential provider. No AWS secrets are accepted by this form.</div><div class="settings-actions"><button class="button" type="submit">Unlock workspace</button></div></form>`);setTimeout(()=>$('#console-token')?.focus(),40);}
function confirmInspect(id){const c=state.connections.find(x=>x.id===id);if(!c)throw new Error('Connection not configured.');const desc=c.kind==='aws'?`Expected account ${c.expected_account_id}; Regions ${c.regions.join(', ')}. Identity must match before resource collection begins.`:c.kind==='kubernetes'?`Read the configured context in namespaces ${c.namespaces.join(', ')}. No secrets or write operations.`:'Read version, container, volume and network metadata from the configured local Unix socket.';openModal('Inspect '+c.name,'This collects metadata. It does not execute faults or test application traffic.',`<p class="text-block">${esc(desc)}</p><div class="section-gap">${info('Partial results are preserved. Access denial, time limits and truncated listings remain explicit collection gaps.')}</div>`,button('Cancel','close-modal','',true)+button('Start read-only inspection','inspect-confirm',`data-id="${esc(id)}"`));}
async function performInspect(id){if(state.mode!=='service')throw new Error('Live inspection requires the local service.');const b=$('[data-action="inspect-confirm"]');b.disabled=true;b.textContent='Collecting metadata…';try{const entry=await api('inspect',{method:'POST',body:{connection_id:id}});closeModal();await refresh();location.hash='inventory';state.inventoryRef=entry.meta.ref;render();showDetail(entry.meta.ref);toast('Snapshot saved. Review coverage before interpreting the inventory.');}finally{if(b.isConnected){b.disabled=false;b.textContent='Start read-only inspection';}}}
async function doAction(buttonEl){const a=buttonEl.dataset.action,reference=buttonEl.dataset.ref;switch(a){case 'menu':$('#sidebar').classList.toggle('open');break;case 'route':location.hash=buttonEl.dataset.route;break;case 'unlock':unlock();break;case 'setup':setup();break;case 'config-example':configExample();break;case 'close-modal':closeModal();break;case 'close-drawer':$('#drawer').close();break;case 'detail':showDetail(reference);break;case 'resource':showResource(reference,buttonEl.dataset.id);break;case 'import':openImport();break;case 'review-import':await reviewImport();break;case 'commit-import':await commitImport();break;case 'load-example':$('#import-json').value=JSON.stringify(APP_DATA.examples,null,2);state.importReviewed=false;$('#commit-import').disabled=true;$('#import-review').innerHTML=info('Synthetic workflow loaded into the editor. Review before importing.','warning');break;case 'load-catalogue':$('#import-json').value=JSON.stringify(APP_DATA.catalogue,null,2);state.importReviewed=false;$('#commit-import').disabled=true;break;case 'new-scenario':newScenario();break;case 'new-run':newRun(reference);break;case 'revise':{const r=clone(get(reference).record);r.revision++;openImport({schema_version:'1.0',kind:'validation_bundle',records:[r]});break;}case 'evaluate':await evaluateRun(reference);break;case 'report':await makeReport(reference);break;case 'export':await exportWorkspace();break;case 'export-record':{const r=get(reference).record;download(r.id+'-bundle.json',JSON.stringify(lineage(reference),null,2));toast('Export includes loaded referenced records, not credentials.');break;}case 'download-report':await downloadReport(reference);break;case 'copy':await navigator.clipboard.writeText(buttonEl.dataset.value);toast('Reference copied.');break;case 'connection-example':{const e=latestSnapshots().find(x=>x.record.data.connection_id===buttonEl.dataset.id);if(e)showDetail(e.meta.ref);else toast('No example snapshot for this connector. Run the local service to inspect it.');break;}case 'inspect':confirmInspect(buttonEl.dataset.id);break;case 'inspect-confirm':await performInspect(buttonEl.dataset.id);break;case 'snapshot-inventory':state.inventoryRef=reference;$('#drawer').close();location.hash='inventory';render();break;case 'more-inventory':state.inventoryLimit+=200;render();break;case 'observe':{if(state.mode!=='service')throw new Error('Observation runs require the local service and a non-synthetic snapshot.');const e=await api('observe',{method:'POST',body:{snapshot_ref:reference}});await refresh();location.hash='runs';showDetail(e.meta.ref);break;}case 'backup':if(state.mode!=='service')throw new Error('The preview has no database. Export JSON or run the local service.');download('validation-workspace.sqlite3',await api('backup',{blob:true}));toast('Consistent database backup downloaded. Store it securely.');break;default:throw new Error('Unknown action.');}}
document.addEventListener('click',async event=>{const el=event.target.closest('[data-action]');if(!el)return;event.preventDefault();if(el.disabled)return;try{await doAction(el);}catch(error){toast(error.message||String(error),true);}});
document.addEventListener('input',event=>{const el=event.target;if(el.id==='import-json'){state.importReviewed=false;const b=$('#commit-import');if(b)b.disabled=true;}if(el.matches('[data-filter]')&&el.tagName==='INPUT'){const start=el.selectionStart;filterFor(state.route)[el.dataset.filter]=el.value;const id=el.id;render();const next=$('#'+id);next.focus();next.setSelectionRange(start,start);}});
document.addEventListener('change',async event=>{const el=event.target;try{if(el.matches('[data-filter]')&&el.tagName==='SELECT'){filterFor(state.route)[el.dataset.filter]=el.value;render();}if(el.matches('[data-snapshot-select]')){state.inventoryRef=el.value;state.inventoryLimit=200;render();}if(el.id==='json-file'&&el.files.length){const file=el.files[0];if(file.size>5*1024*1024)throw new Error('File exceeds 5 MiB.');$('#import-json').value=await file.text();state.importReviewed=false;$('#commit-import').disabled=true;$('#import-review').innerHTML=info('File loaded. Review the JSON before importing.');}}catch(err){toast(err.message,true);}});
document.addEventListener('submit',async event=>{if(event.target.id!=='unlock-form')return;event.preventDefault();const token=$('#console-token').value;state.token=token;try{const [workspace,config]=await Promise.all([api('workspace'),api('config')]);state.unlocked=true;state.entries=workspace.records;state.audit=workspace.audit;state.connections=config.connections;closeModal();render();toast('Local workspace unlocked. No environment has been inspected by unlocking it.');}catch(err){state.token='';toast(err.message,true);}});
window.addEventListener('hashchange',()=>{state.route=location.hash.slice(1)||'overview';$('#sidebar').classList.remove('open');render();window.scrollTo(0,0);});
document.addEventListener('keydown',event=>{if(event.key==='Escape')$('#sidebar').classList.remove('open');if(event.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(event.target.tagName)&&!$('dialog[open]')){const search=$('input[type="search"]');if(search){event.preventDefault();search.focus();}}});
async function init(){state.route=location.hash.slice(1)||'overview';if(state.mode==='preview'){const all=[...APP_DATA.catalogue.records,...APP_DATA.examples.records];for(const r of all)state.entries.push({record:clone(r),meta:{ref:rid(r),sha256:await hash(r),origin:r.simulated?'example':'catalogue',created_at:'2026-10-21T10:00:00Z'}});state.audit=[{seq:1,at:now(),action:'preview_loaded',detail:{note:'Synthetic fixtures loaded in browser memory. No connection attempt.'}}];state.connections=[{id:'example-aws',name:'Example AWS account',kind:'aws',profile:'example-readonly',expected_account_id:'123456789012',regions:['eu-central-1'],services:['ec2','eks','ecs','lambda','rds','cloudwatch']},{id:'example-docker',name:'Example Docker engine',kind:'docker'},{id:'example-podman',name:'Podman connector design',kind:'podman'},{id:'example-kubernetes',name:'Example Kubernetes namespace',kind:'kubernetes',context:'example-local',namespaces:['example']}];}render();}
init().catch(err=>toast(err.message,true));
